import type { SeedData, SeedDish } from "@solo/domain/types";
import data from "./seed.json";

/** Countries, London suggestions and dishes, generated by `npm run solo:seed`. */
export const seed: SeedData = data as SeedData;

/** The countries that have at least one London suggestion. */
export function listedCountries(seed: SeedData): Set<string> {
  return new Set(seed.restaurants.map((r) => r.countryIso2));
}

export function dishesFor(seed: SeedData, iso2: string): SeedDish[] {
  return seed.dishes.filter((d) => d.countryIso2 === iso2);
}
